add_filter( 'woocommerce_is_sold_individually', 'perfectpixel_conditional_sold_individually', 20, 2 );

function perfectpixel_conditional_sold_individually( $sold_individually, $product ) {
	if ( $sold_individually || ! $product ) {
		return $sold_individually;
	}
	$limit = (int) '{{force_qty1_stock_below}}';
	if ( $limit > 0 && $product->managing_stock() && (int) $product->get_stock_quantity() <= $limit ) {
		return true;
	}
	$categories = wp_parse_id_list( '{{force_qty1_category_ids}}' );
	$id         = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	if ( $categories && has_term( $categories, 'product_cat', $id ) ) {
		return true;
	}
	return $sold_individually;
}
